import java.util.*;

public class Main {
    static int best;
    static int[][] sortedCourses;
    static int n;

    static void backtrack(int index, int time, int count) {
        best = Math.max(best, count);
        if (index == n) return;
        int duration = sortedCourses[index][0], lastDay = sortedCourses[index][1];
        if (time + duration <= lastDay) {
            backtrack(index + 1, time + duration, count + 1);
        }
        backtrack(index + 1, time, count);
    }

    static int scheduleCourse(int[][] courses) {
        n = courses.length;
        sortedCourses = courses.clone();
        Arrays.sort(sortedCourses, (a, b) -> a[1] - b[1]);
        best = 0;
        backtrack(0, 0, 0);
        return best;
    }

    public static void main(String[] args) {
        System.out.println(scheduleCourse(new int[][]{{100, 200}, {200, 1300}, {1000, 1250}, {2000, 3200}}));
        System.out.println(scheduleCourse(new int[][]{{1, 2}}));
    }
}

