int scheduleCourse(vector<vector<int>>& courses) {
    n = courses.size();
    sortedCourses = courses;
    sort(sortedCourses.begin(), sortedCourses.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    });
    best = 0;
    backtrack(0, 0, 0);
    return best;
}

