import java.util.*;

public class Main {
    static int scheduleCourse(int[][] courses) {
        int[][] sorted = courses.clone();
        Arrays.sort(sorted, (a, b) -> a[1] - b[1]);

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long time = 0;

        for (int[] course : sorted) {
            int duration = course[0], lastDay = course[1];
            time += duration;
            maxHeap.add(duration);
            if (time > lastDay) {
                time -= maxHeap.poll();
            }
        }
        return maxHeap.size();
    }

    public static void main(String[] args) {
        System.out.println(scheduleCourse(new int[][]{{100, 200}, {200, 1300}, {1000, 1250}, {2000, 3200}}));
        System.out.println(scheduleCourse(new int[][]{{1, 2}}));
    }
}

