#include <bits/stdc++.h>
using namespace std;

int scheduleCourse(vector<vector<int>>& courses) {
    vector<vector<int>> sorted = courses;
    sort(sorted.begin(), sorted.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    });

    priority_queue<int> maxHeap;
    long long time = 0;

    for (auto& course : sorted) {
        int duration = course[0], lastDay = course[1];
        time += duration;
        maxHeap.push(duration);
        if (time > lastDay) {
            time -= maxHeap.top();
            maxHeap.pop();
        }
    }
    return maxHeap.size();
}

int main() {
    vector<vector<int>> courses1 = {{100, 200}, {200, 1300}, {1000, 1250}, {2000, 3200}};
    cout << scheduleCourse(courses1) << endl;
    vector<vector<int>> courses2 = {{1, 2}};
    cout << scheduleCourse(courses2) << endl;
    return 0;
}
